import { FC, useEffect, useRef, useState } from "react";
import {
  HomeHeroActions,
  HomeResumeButton,
  HomeSectionContainer,
  HomeSectionContentWrapper,
  HomeSectionPrimaryTitle,
  HomeSectionSecondaryTitle,
  HomeSectionTitle,
  HomeSectionWrapper,
} from "./home-section-components";
import { SITE } from "../../config/site";
import { useGsapReveal } from "../../hooks/useGsapReveal";

const texts = [
  "Frontend Developer",
  "React Developer",
  "Next.JS Developer",
  "UI Developer",
  "JavaScript Developer",
  "Full Stack Developer (Node.js)",
];
type HomeProps = {
  isLoading: boolean;
};

const Home: FC<HomeProps> = ({ isLoading }) => {
  const [currentTextIndex, setCurrentTextIndex] = useState(0);
  const containerRef = useRef<HTMLElement | null>(null);

  useGsapReveal(containerRef, { y: 20 }, !isLoading);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentTextIndex((prevIndex) => (prevIndex + 1) % texts.length);
    }, 4000);
    return () => clearInterval(interval);
  }, []);
  if (isLoading) {
    return (
      <HomeSectionContainer id="home" ref={containerRef}>
        <HomeSectionWrapper>
          <HomeSectionContentWrapper>
            <div className="skeleton skeleton-text skeleton-subtitle" />
            <div className="skeleton skeleton-text skeleton-title" />
            <div className="skeleton skeleton-text skeleton-tagline" />
          </HomeSectionContentWrapper>
        </HomeSectionWrapper>
      </HomeSectionContainer>
    );
  }

  return (
    <>
      <HomeSectionContainer id="home" ref={containerRef}>
        <HomeSectionWrapper>
          <HomeSectionContentWrapper>
            <HomeSectionPrimaryTitle data-animate="fade">
              Hello, This is
            </HomeSectionPrimaryTitle>
            <HomeSectionSecondaryTitle data-animate="fade">
              <span>D</span>evendra <span>G</span>olakoti
            </HomeSectionSecondaryTitle>
            <HomeSectionTitle data-animate="fade">
              And I'm a{" "}
              <span className="typing">{texts[currentTextIndex]}</span>
            </HomeSectionTitle>
            <HomeHeroActions data-animate="fade">
              <span className="home-resume-cta">
                <span
                  className="home-resume-cta__pulse"
                  aria-hidden="true"
                />
                <HomeResumeButton
                  href={SITE.resumePath}
                  download="Devendra-Golakoti-Resume.pdf"
                  className="home-resume-btn premium-glow-btn"
                >
                  <span className="home-resume-btn__content">
                    <i className="fas fa-download" aria-hidden="true" />
                    Download Resume
                  </span>
                </HomeResumeButton>
              </span>
            </HomeHeroActions>
          </HomeSectionContentWrapper>
        </HomeSectionWrapper>
      </HomeSectionContainer>
    </>
  );
};

export default Home;
